import json
from pathlib import Path

import pytest

from aiotlse2109 import Duplex, PortStatus, ProtocolError
from aiotlse2109._protocol import encode_password, parse_status, password_encoding

HTML = (Path(__file__).parent / "fixtures" / "main.htm").read_text()


@pytest.mark.parametrize(
    ("password", "expected"),
    [
        ("admin", "WaQ7xbhc9TefbwK"),
        ("a-long-password-over-15", "W0qgxL9a8dUBw18MCKUYM5M"),
        ("test😀", "77Vti0hc9TefbwK"),
    ],
)
def test_encoding_matches_firmware_javascript(password, expected):
    # Vectors generated by the switch's actual cryp_new.js with fake passwords.
    assert encode_password(password) == expected


def test_semicolon_optional_in_password_encoding():
    assert password_encoding("<script>var encryptType = 5\n</script>") == 5


def test_recorded_firmware_snapshot():
    snapshot = parse_status(HTML)
    assert snapshot.device.model == "TL-SE2109"
    assert snapshot.device.firmware_version == "1.8.0 Build 20250331 Rel.32620"
    assert not snapshot.device.cloud_connected
    assert len(snapshot.ports) == 9  # Firmware pads its arrays to eleven entries.
    assert snapshot.sampled_at.utcoffset().total_seconds() == 0
    port = snapshot.port(1)
    assert port.status == PortStatus.UP
    assert port.negotiated_speed_mbps == 2500
    assert port.duplex == Duplex.FULL
    assert port.rx_bps == 263_000
    assert port.tx_bps == 6_259_000
    assert port.rx_mbps == 0.263
    assert port.tx_mbps == 6.259
    assert snapshot.port(2).status == PortStatus.DOWN
    assert snapshot.port(2).negotiated_speed_mbps is None
    assert snapshot.port(2).duplex is None
    assert snapshot.port(9).port_type_code == 1


@pytest.mark.parametrize(
    ("code", "speed", "duplex"),
    [
        (0, None, None),
        (1, None, None),
        (2, 10, Duplex.HALF),
        (3, 10, Duplex.FULL),
        (4, 100, Duplex.HALF),
        (5, 100, Duplex.FULL),
        (6, 1000, Duplex.FULL),
        (7, 2500, Duplex.FULL),
        (8, 10000, Duplex.FULL),
    ],
)
def test_all_link_speed_codes(code, speed, duplex):
    html = HTML.replace("spd_act:[7,", f"spd_act:[{code},")
    port = parse_status(html).port(1)
    assert port.link_up == (code != 0)
    assert port.negotiated_speed_mbps == speed
    assert port.duplex == duplex


def test_disabled_port_does_not_report_stale_link_or_rates():
    port = parse_status(HTML.replace("state:[1,", "state:[0,", 1)).port(1)
    assert port.status == PortStatus.DISABLED
    assert not port.link_up
    assert port.negotiated_speed_mbps is None
    assert port.rx_bps == port.tx_bps == 0


@pytest.mark.parametrize(
    ("old", "new"),
    [
        ("max_port_num = 9", "max_port_num = 8"),
        ("max_port_num = 9", "max_port_num = 9+1"),
        ("max_port_num = 9", "max_port_num = 9\n+1"),
        ("port_info = {", "port_info = function() {"),
        ("spd_act:[7,", "spd_act:[99,"),
        ("state:[1,", "state:[2,"),
        ("rx_rate:[263,", "rx_rate:[-1,"),
        ("rx_rate:[263,", "rx_rate:[true,"),
        ("rx_rate:[263,", "rx_rate:[1.5,"),
        ("rx_rate:[263,", "rx_rate:[doSomething(),"),
        ("rx_rate:[263,0,11080,11365,0,0,616,0,19943,0,0]", "rx_rate:[1]"),
        ('hardwareStr:["TL-SE2109"]', 'hardwareStr:["Some other switch"]'),
        ("var port_info", "var missing_info"),
        ("cloud_status = 1", "cloud_status = true"),
        ("cloud_status = 1", "cloud_status = 2"),
        ("nms_status = 0", 'nms_status = "0"'),
    ],
)
def test_malformed_or_unsupported_responses(old, new):
    assert old in HTML
    with pytest.raises(ProtocolError):
        parse_status(HTML.replace(old, new, 1))


def test_escaped_device_description():
    # Use JSON serialization to reflect escaped strings in a firmware literal.
    description = '机房 } "quoted" \\ path'
    html = HTML.replace(
        'descriStr:["TL-SE2109"]', f"descriStr:[{json.dumps(description)}]"
    )
    assert parse_status(html).device.description == description


def test_json_normalization_preserves_string_contents():
    description = 'keys: bare_key: $key: endings: ,} ,] escaped: \\ "quoted"'
    html = HTML.replace(
        'descriStr:["TL-SE2109"]', f"descriStr:[{json.dumps(description)}]"
    )
    assert parse_status(html).device.description == description


def test_duplicate_fields_are_rejected():
    html = HTML.replace("rx_rate:[263,", "rx_rate:[],rx_rate:[263,")
    with pytest.raises(ProtocolError):
        parse_status(html)


def test_all_cloud_flags_are_validated_even_when_disconnected():
    html = HTML.replace("cloud_status = 1", "cloud_status = 0")
    html = html.replace("var nms_status", "var missing_nms_status")
    with pytest.raises(ProtocolError):
        parse_status(html)


def test_windows_line_endings():
    assert len(parse_status(HTML.replace("\n", "\r\n")).ports) == 9


def test_snapshot_port_validation():
    with pytest.raises(ValueError):
        parse_status(HTML).port(0)
